{
  "version": 8,
  "sources": {
    "osm-vector": {
      "type": "vector",
      "tiles": ["https://tiles.exemplo.com/{z}/{x}/{y}.pbf"],
      "minzoom": 0,
      "maxzoom": 14
    }
  },
  "layers": [
    { "id": "bg", "type": "background", "paint": { "background-color": "#0b0d10" } },
    {
      "id": "roads",
      "type": "line",
      "source": "osm-vector",
      "source-layer": "transportation",
      "paint": {
        "line-color": ["match",
          ["get", "class"],
          "motorway", "#f59e0b",
          "primary",  "#84cc16",
          /* default */ "#374151"
        ],
        "line-width": ["interpolate", ["linear"], ["zoom"],
          8, 0.5,
          14, 3,
          18, 8
        ]
      }
    }
  ]
}

// React + MapLibre — componente client (use client)
"use client";
import { useEffect, useRef } from "react";
import maplibregl from "maplibre-gl";
import "maplibre-gl/dist/maplibre-gl.css";

export function CityMap({ lat, lng, zoom = 12 }: { lat: number; lng: number; zoom?: number }) {
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!ref.current) return;
    const map = new maplibregl.Map({
      container: ref.current,
      style: "https://demotiles.maplibre.org/style.json", // troque pelo seu
      center: [lng, lat],
      zoom,
      pitch: 30,
      bearing: -10,
    });

    new maplibregl.Marker({ color: "#84cc16" })
      .setLngLat([lng, lat])
      .addTo(map);

    map.on("load", () => {
      // adicionar source + layer programaticamente
      map.addSource("alertas", {
        type: "geojson",
        data: "/api/alertas.geojson",
      });
      map.addLayer({
        id: "alertas-circle",
        type: "circle",
        source: "alertas",
        paint: {
          "circle-radius": ["interpolate", ["linear"], ["get", "severity"], 1, 4, 5, 16],
          "circle-color": ["match",
            ["get", "type"],
            "incendio", "#ef4444",
            "alagamento", "#3b82f6",
            "#6b7280",
          ],
          "circle-opacity": 0.7,
        },
      });
    });

    return () => map.remove();
  }, [lat, lng, zoom]);

  return <div ref={ref} style={{ width: "100%", height: 480 }} />;
}
